const resourceDrafts={CAPITAL:'Capital Readiness Worksheet\n\n1. Project/company context and province.\n2. Financing purpose.\n3. Stated amount, timing and unknowns.\n4. Existing financing and participant authority, through appropriate intake.\n5. Supporting information available and missing.\n6. Next useful discussion and who should attend.\n\nA discussion aid, not an approval or lender requirements list.',REVIEW:'Refinance Preparation Sheet\n\n1. What prompts the review?\n2. Which current debt terms and dates need confirming?\n3. What changed at the property or business?\n4. What information is ready or missing?\n5. What outcome is the owner seeking?\n6. What should the owner and broker answer next?\n\nA preparation aid; financing remains subject to review.',SIGNAL:'Project-to-Conversation Checklist\n\n1. What dated source supports the event?\n2. Which entity and authorized participant are involved?\n3. Does this match the broker mandate?\n4. What financing need and timing are confirmed or unknown?\n5. What permissioned introduction or appropriate contact route exists?\n6. What useful question or proof asset justifies the conversation?\n\nA public signal is not financing intent.'};
const writtenDrafts={B01:'Planning a construction project? Before asking how much you can borrow, map what the capital needs to do.\n\nUse a one-page capital-readiness worksheet. Write down the project stage, location and the next decision you need to make. Separate the total project budget from the financing amount you want to discuss. Add timing, existing financing and missing information. Anything you do not know stays marked as unknown.\n\nYou now have an agenda for a useful financing discussion. Message CAPITAL if you would like the worksheet. It is a preparation tool; financing remains subject to review.',B02:'Start your commercial refinance conversation with the existing debt—not a rate headline.\n\nWhy are you reviewing the financing? Which terms and dates need confirming? What has changed at the property or business? What information is ready, and what is missing? What do you want the next arrangement to achieve?\n\nClearly identifying unknowns helps shape the conversation. These questions are in a Refinance Preparation Sheet. Message REVIEW if a copy would be useful.',P01:'A permit tells you a project moved. It does not tell you the sponsor needs financing.\n\nWho is the sponsor? Who can discuss financing? Does it fit your mandate? Is the financing need confirmed, or are we still researching?\n\nThat is the workflow we are prototyping in KommercialOS: Client Brain for fit, project briefs separating evidence from assumptions, and Chief of Staff to organize research and follow-up. The current version uses sample data. Live sources and agent integrations remain engineering work.\n\nMessage SIGNAL for the Project-to-Conversation Checklist. If useful, we can discuss the prototype.'};
function contentPage(){return head('Content with a purpose.','A useful resource, a relevant conversation, and a measurable next step.',external(projectLinks.notion,'Open Notion Content Bible'))+`<div class="steps"><span>Client Brain</span><span>One problem</span><span>Useful resource</span><span>Claims & broker review</span><span>Diagnostic conversation</span><span>Held qualified outcome</span></div><div class="notice" style="margin-bottom:20px">Draft workspace only. Borrower origination and platform acquisition are separate funnels. No publishing, automatic DMs or paid campaigns are connected. Platform content also requires internal-pilot readiness.</div><div class="filters" style="padding-left:0"><select id="contentMotion" onchange="contentFilter()" aria-label="Content audience"><option>All audiences</option><option>Borrower</option><option>Referral</option><option>Platform</option></select><span class="subtle">12 topic candidates · 3 starter drafts · 3 resource drafts</span></div><div class="cards" id="contentCards">${contentTopics.map(contentCard).join('')}</div>`}
function contentCard(t){const d=state.contentDrafts?.[t[0]];return `<article class="panel playcard"><span class="eyebrow">${t[0]} · ${t[1]} · ${d?.reviewed?'REVIEW RECORDED':'DRAFT'}</span><h2>${esc(t[2])}</h2><p>${esc(t[3])}</p><p><b>Resource:</b> ${esc(t[5])}<br><b>CTA:</b> ${esc(t[4])}</p><button onclick="contentDetail('${t[0]}')">${writtenDrafts[t[0]]?'Edit starter draft':'Build content brief'} →</button></article>`}
function contentFilter(){const m=$('#contentMotion').value;$('#contentCards').innerHTML=contentTopics.filter(t=>m==='All audiences'||t[1]===m).map(contentCard).join('')}
function contentDetail(id){const t=contentTopics.find(t=>t[0]===id),d=state.contentDrafts?.[id];modal(t[2],'CONTENT BIBLE · '+t[1].toUpperCase(),`<p><b>Hook:</b> ${esc(t[3])}<br><b>Resource:</b> ${esc(t[5])}<br><b>Diagnostic:</b> ${esc(t[6])}</p><p><b>Suggested owners:</b> Offer Strategist → Content Creator → Evidence Collector → publishing broker. Chief of Staff tracks the handoff.</p><label>Editable draft / brief<textarea id="contentText" rows="10" style="width:100%;margin-top:8px">${esc(d?.text||writtenDrafts[id]||'Audience: '+t[1]+'\nProblem: '+t[2]+'\nHook: '+t[3]+'\nTeaching steps: [draft]\nEvidence needed: [identify]\nResource: '+t[5]+' [not yet produced]\nCTA: '+t[4]+'\nDiagnostic: '+t[6])}</textarea></label><label class="task"><input type="checkbox" id="contentEvidence" ${d?.evidence?'checked':''}>Claims and source requirements reviewed</label><label class="task"><input type="checkbox" id="contentResource" ${d?.resource?'checked':''}>Promised resource is available and appropriate</label><label class="task"><input type="checkbox" id="contentBroker" ${d?.broker?'checked':''}>Publishing broker reviewed this exact draft</label><div class="notice">Editing the draft invalidates its prior review. Review flags are local notes, not publishing authorization or evidence of compliance. ${t[1]==='Platform'?'Public product promotion also remains subject to pilot-readiness review.':''}</div>${resourceDrafts[t[4]]?`<h3>Resource draft</h3><p style="white-space:pre-wrap">${esc(resourceDrafts[t[4]])}</p>`:''}`,`<button onclick="downloadContent('${id}')">Download text</button><button class="primary" onclick="saveContent('${id}')">Save draft / review</button>`)}
function saveContent(id){state.contentDrafts??={};let old=state.contentDrafts[id],text=$('#contentText').value;if(!text.trim()){toast('Add draft text before saving.');return}let changed=old&&old.text!==text;const evidence=changed?false:$('#contentEvidence').checked,resource=changed?false:$('#contentResource').checked,broker=changed?false:$('#contentBroker').checked;state.contentDrafts[id]={text,evidence,resource,broker,reviewed:evidence&&resource&&broker,updatedAt:new Date().toISOString()};log('Saved local content draft '+id+(changed?' · review reset':''));$('#dialog').close();render();toast(changed?'Draft changed. Review flags reset.':'Draft saved locally. Nothing published.')}
function downloadText(name,text){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function downloadContent(id){downloadText('kommercialos-'+id+'-draft.txt',$('#contentText').value+'\n\nDraft for review. Not published.\n'+(resourceDrafts[contentTopics.find(t=>t[0]===id)[4]]||''))}
function billingRule(b){const holds=[];if(!b.agreement?.trim())holds.push('Example agreement reference missing');if(!Number.isFinite(Number(b.amount))||Number(b.amount)<=0)holds.push('Positive agreed amount required');if(!b.tax?.trim())holds.push('Reviewed tax mapping missing');if(!b.accepted)holds.push('Required buyer/client acceptance missing');if(!b.evidence)holds.push('Qualification / deliverable evidence missing');if(!b.unique)holds.push('Duplicate, bundle and allocation check missing');if(b.product==='Held qualified appointment'&&(b.outcome!=='Held qualified'))holds.push('Booked, cancelled or no-show is not held qualified');return {status:holds.length?'Hold':'Sample conditions satisfied',holds,issuanceEnabled:false};}
function billingPage(){let a=state.billingScenarios||[];return head('Bill for the agreed outcome.','Contract first. Verified evidence next. Invoice and payment only through approved integrations.',`<button class="primary" onclick="billingForm()">＋ Test a billing scenario</button>`)+`<div class="stats"><div class="stat"><div class="label">Sample review scenarios</div><div class="value">${a.length}</div><small>Local simulation · not a billing ledger</small></div><div class="stat"><div class="label">Billr connection</div><div class="value" style="font-size:22px">Unconnected</div><small>No provider account or invoice access</small></div><div class="stat"><div class="label">Payment collection</div><div class="value" style="font-size:22px">Disabled</div><small>No Stripe connection or charges</small></div><div class="stat"><div class="label">Invoice / collected totals</div><div class="value">—</div><small>Unknown · no live billing data</small></div></div><div class="notice" style="margin-bottom:20px">Billing sandbox only. A sample outcome, content request or agent task cannot create a charge. Proposed appointment default: held, qualified and accepted. Actual terms must come from a signed agreement; no default prices are assumed.</div><div class="plan"><section><div class="panel"><div class="panelhead"><div><h2>Outcome review scenarios</h2><p>Passing sample checks never enables invoicing.</p></div></div><div class="tablewrap"><table><thead><tr><th>PRODUCT / EXAMPLE AGREEMENT</th><th>SAMPLE AMOUNT</th><th>RESULT</th></tr></thead><tbody>${a.map(b=>{let r=billingRule(b);return `<tr><td>${esc(b.product)}<small>${esc(b.agreement||'Missing reference')}</small></td><td>${esc(b.currency)} ${esc(b.amount)}</td><td><span class="tag ${r.holds.length?'amber':'teal'}">${r.status}</span><small>${esc(r.holds.join('; ')||'Manual sample only · issuance disabled')}</small></td></tr>`}).join('')||'<tr><td colspan="3" class="empty">No sample scenarios. Test the agreed-outcome checks.</td></tr>'}</tbody></table></div></div></section><section><div class="panel" style="padding:23px"><h2>Product triggers</h2>${[['Qualified lead','Permitted delivery + agreed qualification + acceptance'],['Held qualified appointment','Actual held outcome + criteria + acceptance'],['Setup / custom build','Contracted deposit or accepted milestone'],['SaaS','Valid agreed billing period and active plan'],['Agent usage','Explicit billable meter, verified usage and limits']].map(([h,p])=>`<div class="wirebox"><b>${h}</b><p>${p}</p></div>`).join('')}${external(projectLinks.billing,'Canonical billing SOP')}</div><div class="panel" style="padding:23px"><h2>Chief of Staff handoff</h2><p class="subtitle">Coordinator proposes candidates and assigns exceptions. An authorized billing reviewer checks agreement, qualification, price, tax, duplicates and credits. Ledger and provider integration are still engineering work.</p><p class="subtitle">One lead plus one later appointment is not automatically two fees. Apply bundle, upgrade, credit and reschedule rules. Keep mortgage compensation separate from platform/service billing.</p>${external(projectLinks.github,'Engineering backlog')}</div></section></div>`}
function billingForm(){modal('Test a billing scenario','SYNTHETIC DATA ONLY',`<form id="billingForm" class="formgrid"><label>Product<select name="product"><option>Held qualified appointment</option><option>Qualified lead</option><option>Setup milestone</option><option>Custom-build milestone</option><option>SaaS billing period</option><option>Agent usage</option></select></label><label>Example agreement reference<input name="agreement" placeholder="DEMO-AGREEMENT-001"></label><label>Example agreed amount<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Currency<select name="currency"><option>CAD</option><option>USD</option></select></label><label>Example tax mapping<input name="tax" placeholder="Reviewed example tax code"></label><label>Appointment outcome<select name="outcome"><option>Booked</option><option>Held qualified</option><option>Held unqualified</option><option>No-show</option><option>Cancelled</option><option>Not applicable</option></select></label></form><label class="task"><input id="billAccepted" type="checkbox">Sample customer acceptance recorded</label><label class="task"><input id="billEvidence" type="checkbox">Sample qualification/deliverable evidence reviewed</label><label class="task"><input id="billUnique" type="checkbox">Sample duplicate, bundle and allocation checks reviewed</label><div class="notice">Do not use real borrower or payment information. This only evaluates local example conditions; no financial side effects or authoritative contract validation.</div>`,`<button class="primary" onclick="saveBillingScenario()">Evaluate sample scenario</button>`)}
function saveBillingScenario(){let f=$('#billingForm');if(!f.reportValidity())return;let b=Object.fromEntries(new FormData(f));Object.assign(b,{id:Date.now(),accepted:$('#billAccepted').checked,evidence:$('#billEvidence').checked,unique:$('#billUnique').checked});state.billingScenarios??=[];state.billingScenarios.push(b);log('Evaluated synthetic billing scenario; invoice issuance disabled');$('#dialog').close();render();toast(billingRule(b).status+' · no invoice created')}
function reportMeetings(){const month=state.reportingMonth||'2026-10';return state.meetings.filter(m=>(m.heldAt||m.date||'').slice(0,7)===month)}
function reportControl(){return `<div class="reportcontrol"><label>Sample reporting month <input aria-label="Sample reporting month" type="month" value="${esc(state.reportingMonth||'2026-10')}" onchange="state.reportingMonth=this.value;save();render()"></label><span>Held-qualified totals use recorded outcome dates; sample records have example dates. Upcoming bookings and pipeline totals cover the full workspace.</span></div>`}

