let yieldLoading=false,yieldError='';
function validYield(v){if(v===null||v===undefined||typeof v==='boolean')return null;let s=String(v).trim();if(!s||s.toUpperCase()==='NA')return null;let n=Number(s);return Number.isFinite(n)?n:null}
function parseBondData(data,today=new Date().toISOString().slice(0,10)){if(!Array.isArray(data?.observations)||!data.seriesDetail)throw Error('Unexpected official data format');for(const s of bondSeries){let label=data.seriesDetail[s.key]?.label||'';if(!new RegExp('\\b'+s.tenor+'[- ]year\\b','i').test(label))throw Error('Series metadata does not match tenor')}let dates=new Set(),rows=data.observations.filter(o=>/^\d{4}-\d{2}-\d{2}$/.test(o.d)&&o.d<=today).sort((a,b)=>b.d.localeCompare(a.d)).filter(o=>{if(dates.has(o.d))return false;dates.add(o.d);return bondSeries.some(s=>validYield(o[s.key]?.v)!==null)}).slice(0,10);if(!rows.length)throw Error('No published observations found');return {mode:'api',fetchedAt:new Date().toISOString(),observations:rows}}
function bondSummary(data){return bondSeries.map(s=>{let rows=data.observations.filter(o=>validYield(o[s.key]?.v)!==null).sort((a,b)=>b.d.localeCompare(a.d));let current=rows[0],previous=rows[1],value=current?validYield(current[s.key].v):null;return {...s,value,date:current?.d||'',previousDate:previous?.d||'',change:previous&&value!==null?Math.round((value-validYield(previous[s.key].v))*10000)/100:null}})}
async function refreshYields(){if(yieldLoading)return;yieldLoading=true;yieldError='';if(page==='market')render();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(bondEndpoint,{signal:controller.signal,credentials:'omit',cache:'no-store'});if(!r.ok)throw Error('Official endpoint returned '+r.status);const parsed=parseBondData(await r.json());state.yieldData=parsed;save();}catch(e){yieldError='Refresh unavailable. Retained observations have not been refreshed; open the official source to verify. '+(e.name==='AbortError'?'Request timed out.':'')}finally{clearTimeout(timer);yieldLoading=false;if(page==='market')render()}}
function safeMarketUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null}catch{return null}}
function intelligenceItems(){return [...marketSeed,...(state.marketNotes||[])].sort((a,b)=>b.date.localeCompare(a.date))}
function marketRelevance(item){if(!state.brain)return {matches:true,reasons:['Activate Client Brain for declared-specialty relevance.']};let b=state.brain.answers,reasons=[],region=item.province==='National'||b.regions.includes(item.province),purpose=item.purposes.some(p=>b.purposes.includes(p)),asset=item.types.some(t=>b.properties.includes(t));if(region)reasons.push(item.province==='National'?'National context':'Selected province');if(purpose)reasons.push('Declared financing specialty');if(asset)reasons.push('Selected property / asset type');let cities=b.cities.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);if(cities.length&&cities.includes(item.city.toLowerCase()))reasons.push('Preferred city');return {matches:region&&(purpose||asset),reasons:reasons.length?reasons:['Outside declared profile tags; review manually.']}}
function marketPage(){let data=state.yieldData||reviewedYields,summary=bondSummary(data),two=summary[0],ten=summary[2],spread=two.value!==null&&ten.value!==null&&two.date===ten.date?Math.round((ten.value-two.value)*100):null;return head('Market intelligence. Context for the next call.','Bond yields, financing-relevant news and municipal change tracking — with sources, dates and uncertainty.',`<button onclick="marketNoteForm()">＋ Add source note</button><button class="primary" onclick="refreshYields()" ${yieldLoading?'disabled':''}>${yieldLoading?'Refreshing official yields…':'↻ Refresh official yields'}</button>`)+`<div class="notice" style="margin-bottom:18px">${data.mode==='api'?'Yields loaded from Bank of Canada Valet on request.':'Initial yield panel is a reviewed official closing observation from October 15, 2026; use Refresh for the latest published data.'} Observation dates are shown per tenor. Government bond yields are market context, not commercial mortgage quotes, lender spreads or the Bank’s policy rate.</div>${yieldError?`<div class="notice" role="alert" style="margin-bottom:15px">${esc(yieldError)}</div>`:''}<div class="stats">${summary.map(s=>`<div class="stat"><div class="label">GoC benchmark · ${s.tenor} year</div><div class="value">${s.value===null?'—':s.value.toFixed(2)+'%'}</div><small>${esc(s.date||'No observation')} · ${s.change===null?'prior unavailable':(s.change>0?'+':'')+s.change.toFixed(0)+' bps vs '+s.previousDate}</small></div>`).join('')}<div class="stat"><div class="label">10 year minus 2 year</div><div class="value">${spread===null?'—':(spread>0?'+':'')+spread} <em>bps</em></div><small>Same-date observations only</small></div></div><div class="panel"><div class="panelhead"><div><h2>Rate context and source freshness</h2><p>${data.mode==='api'?'Last API retrieval: '+esc(data.fetchedAt):'Source reviewed October 17, 2026 · observation date differs from review date'}. Refresh failure never turns missing data into zero.</p></div>${external(bondSource,'Bank of Canada source')}</div><div class="tablewrap"><table><thead><tr><th>OBSERVATION DATE</th>${bondSeries.map(s=>`<th>${s.tenor} YEAR %</th>`).join('')}</tr></thead><tbody>${data.observations.slice().sort((a,b)=>b.d.localeCompare(a.d)).slice(0,5).map(r=>`<tr><td>${esc(r.d)}</td>${bondSeries.map(s=>`<td>${validYield(r[s.key]?.v)===null?'—':validYield(r[s.key]?.v).toFixed(2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="layout"><section><div class="panel"><div class="panelhead"><div><h2>News, zoning & release watch</h2><p>Curated source review dated October 17, 2026 · news does not auto-refresh with bond yields.</p></div></div><div class="filters"><select id="marketCategory" aria-label="Intelligence category" onchange="marketFilter()"><option>All categories</option><option>Market news</option><option>Housing data</option><option>Zoning</option><option>Upcoming release</option><option>Lender update</option></select><select id="marketRegion" aria-label="Intelligence geography" onchange="marketFilter()"><option>All regions</option><option>National</option><option>BC</option><option>AB</option><option>ON</option></select><label style="font-size:10px"><input type="checkbox" id="marketFit" onchange="marketFilter()"> Client Brain relevance</label></div><div id="marketItems">${intelligenceItems().map(marketItem).join('')}</div></div></section><section><div class="goalcard"><div class="eyebrow">FACT → CONTEXT → QUESTION</div><h2>Prepare a better conversation.</h2><p>Chief of Staff can use a source-backed update to propose research or a content brief. It cannot infer sponsor intent, site entitlement, a rate recommendation or permission to contact.</p><button onclick="nav('chief')" style="margin-top:15px">Open agent coordination →</button></div><div class="panel" style="padding:20px"><h2>Official source watchlist</h2><p class="subtitle">Primary sources to review; these links are not connected news feeds.</p>${[['Bank of Canada · rates',bondSource],['Bank of Canada · Business Outlook Survey','https://www.bankofcanada.ca/publications/bos/'],['CMHC · housing market data','https://www.cmhc-schl.gc.ca/professionals/housing-markets-data-and-research/housing-data/data-tables/housing-market-data'],['Vancouver · zoning amendments','https://vancouver.ca/home-property-development/zoning-land-use-document-library-amendments.aspx'],['Burnaby · zoning rewrite','https://www.burnaby.ca/our-city/projects/zoning-bylaw-rewrite']].map(([n,u])=>`<p>${external(u,n)}</p>`).join('')}</div><div class="notice">Source dates and status do not prove current parcel-level applicability. Check the operative bylaw, maps, transition rules and any later amendment. Proposed, adopted and effective changes are different states.</div></section></div>`}
function marketItem(item){let r=marketRelevance(item),saved=(state.savedMarket||[]).includes(item.id),url=safeMarketUrl(item.url);return `<article class="newsitem"><div class="eyebrow">${esc(item.category)} · ${esc(item.city)} · ${esc(item.date)}</div><h3>${esc(item.title)}</h3><div style="margin:10px 0"><span class="tag ${item.reviewed?'blue':'amber'}">${item.reviewed?'Source reviewed 2026-10-17':'Unverified analyst note'}</span><span class="tag">${esc(item.status)}</span>${item.effective?`<span class="tag teal">Effective ${esc(item.effective)}</span>`:''}</div><p>${esc(item.summary)}</p><div class="wirebox"><b>Broker relevance · interpretation</b><p>${esc(item.why)}</p><p>${esc(r.reasons.join(' · '))}. This is relevance tagging, not investment or lending advice.</p></div><div class="actions" style="align-items:center;flex-wrap:wrap">${url?external(url,esc(item.source)):'<span>Invalid source URL</span>'}<button class="textbutton" onclick="saveMarketItem('${item.id}')">${saved?'Saved ✓':'Save to briefing'}</button><button class="textbutton" onclick="marketContentBrief('${item.id}')">Create content brief →</button></div></article>`}
function marketFilter(){let category=$('#marketCategory').value,region=$('#marketRegion').value,fit=$('#marketFit').checked;$('#marketItems').innerHTML=intelligenceItems().filter(i=>(category==='All categories'||i.category===category)&&(region==='All regions'||i.province===region)&&(fit?marketRelevance(i).matches:true)).map(marketItem).join('')||'<div class="empty">No matching source notes. Broaden the filters or add a reviewed source.</div>'}
function saveMarketItem(id){state.savedMarket??=[];if(!state.savedMarket.includes(id))state.savedMarket.push(id);save();if(page==='market')marketFilter();toast('Source saved to your local briefing list.')}
function marketContentBrief(id){const i=intelligenceItems().find(x=>x.id===id);if(!i)return;let text='MARKET-BASED CONTENT BRIEF · DRAFT\nSource: '+i.source+'\nURL: '+i.url+'\nEvent/publication date: '+i.date+'\nStatus: '+i.status+(i.effective?'\nEffective date: '+i.effective:'')+'\n\nSource summary:\n'+i.summary+'\n\nBroker relevance — interpretation:\n'+i.why+'\n\nAudience: [choose active specialty]\nProblem/question: [draft]\nUseful teaching step: [draft]\nEvidence and latest status: [recheck before publication]\nResource/CTA: [propose]\nReviewer: [assign]\n\nNot published. No site-specific entitlement, financing approval or rate recommendation implied.';modal('Source-backed content brief','DRAFT ONLY',`<textarea id="marketBriefText" rows="16" style="width:100%">${esc(text)}</textarea><p>Recheck current status and applicability before publishing. Copy to an appropriate Content Bible asset for editorial review.</p>`,`<button class="primary" onclick="downloadText('market-content-brief.txt',document.querySelector('#marketBriefText').value)">Download draft</button>`)}
function marketNoteForm(){modal('Add a market source note','MANUAL NOTE · NOT INDEPENDENTLY VERIFIED',`<form id="marketNoteForm" class="formgrid"><label class="wide">Headline<input name="title" required maxlength="200"></label><label>Category<select name="category"><option>Market news</option><option>Housing data</option><option>Zoning</option><option>Upcoming release</option><option>Lender update</option></select></label><label>Province / region<select name="province"><option>BC</option><option>AB</option><option>ON</option><option>National</option></select></label><label>City or Canada<input name="city" required></label><label>Event / publication date<input name="date" type="date" required></label><label>Status<select name="status"><option>Proposed</option><option>Adopted — effective date unverified</option><option>Effective — requires source confirmation</option><option>Published</option><option>Scheduled</option><option>Under review</option></select></label><label>Effective date · optional<input name="effective" type="date"></label><label>Publisher<input name="source" required></label><label>HTTPS source URL<input name="url" type="url" required></label><label class="wide">Source summary<textarea name="summary" required rows="3"></textarea></label><label class="wide">Broker relevance · interpretation<textarea name="why" required rows="3"></textarea></label></form><p>Manually entered notes are marked unverified. An entered effective date is not confirmation that a rule is operative.</p>`,`<button class="primary" onclick="saveMarketNote()">Save unverified source note</button>`)}
function saveMarketNote(){let f=$('#marketNoteForm');if(!f.reportValidity())return;let p=Object.fromEntries(new FormData(f)),url=safeMarketUrl(p.url);if(!url){toast('Use a valid HTTPS source URL without credentials.');return}if(p.effective>new Date().toISOString().slice(0,10)&&p.status.startsWith('Effective')){toast('A future effective date cannot be marked effective. Use Scheduled or an adoption state.');return}if(p.date>new Date().toISOString().slice(0,10)&&p.status!=='Scheduled'){toast('A future event must be marked Scheduled.');return}state.marketNotes??=[];state.marketNotes.push({...p,url,id:'note-'+Date.now(),reviewed:false,purposes:state.brain?.answers.purposes||[],types:state.brain?.answers.properties||[]});log('Added unverified market source note; no alert or publishing action');$('#dialog').close();render();toast('Source note saved for review.')}
function marketPreview(){return `<div class="panel"><div class="panelhead"><div><h2>Market & zoning intelligence</h2><p>Source-linked context for financing conversations.</p></div><button class="textbutton" onclick="nav('market')">Open market desk ↗</button></div>${marketSeed.filter(i=>i.status!=='Scheduled — results not reviewed').slice(0,2).map(i=>`<div class="strategyrow"><div><span class="tag">${esc(i.category)}</span><h3 style="margin-top:7px">${esc(i.title)}</h3><p>${esc(i.date)} · ${esc(i.source)} · reviewed October 17</p></div><button class="textbutton" onclick="nav('market')">Review →</button></div>`).join('')}</div>`}

function marketBriefingContext(){const selected=intelligenceItems().filter(i=>(state.savedMarket||[]).includes(i.id));return '<h3>Selected market context</h3>'+(selected.length?selected.map(i=>'<p>'+esc(i.title)+' · '+esc(i.date)+' · '+esc(i.status)+'<br>'+external(safeMarketUrl(i.url),esc(i.source))+'</p>').join(''):'<p>No source notes saved. Use Market Intelligence to select context; this does not establish financing intent.</p>')}

const pilotSegments=['Commercial finance brokers','Contractors','Commercial real estate teams'];
function pilotRecords(){return state.pilotRecords||[]}
function pilotTotals(segment){const rows=pilotRecords().filter(r=>!segment||r.segment===segment);return {teams:rows.length,activated:rows.filter(r=>r.activated).length,weekly:rows.filter(r=>r.weekly).length,renewed:rows.filter(r=>r.renewed).length,meeting:rows.filter(r=>r.meeting).length}}
function validationPreview(){const t=pilotTotals();return `<div class="notice" style="margin-bottom:20px;display:flex;gap:16px;justify-content:space-between;align-items:center"><div><b>Broker-first launch · prove value through paid pilots</b><br>PMF remains unproven. ${t.teams} locally recorded pilot teams · ${t.meeting} with a confirmed, attributable meeting. Sample opportunity totals are separate.</div><button onclick="nav('validation')">Review validation plan →</button></div>`}
function validationPage(){const t=pilotTotals();return head('Prove the outcome. Earn the renewal.','BC-first validation plan · based on the October 14, 2026 PMF document.',`<a class="textbutton" href="pmf-source.md" download>Download source plan ↓</a><button class="primary" onclick="pilotForm()">＋ Record pilot evidence</button>`)+`<div class="notice">Product-market fit is unproven. Market sizes, prices and gates below are planning assumptions from the supplied document. This browser-local evidence register starts empty and does not infer customer results from synthetic CRM records.</div><div class="stats" style="margin-top:20px">${[['Paid team pilots',t.teams,8],['Activated in 7 days',t.activated,6],['Used 3 of 4 weeks',t.weekly,6],['Renewed at disclosed price',t.renewed,5]].map(([l,n,g])=>`<div class="stat"><div class="label">${l}</div><div class="value">${n} <em>/ ${g} target</em></div><small>Manual evidence · proposed 90-day gates</small></div>`).join('')}</div><div class="panel"><div class="panelhead"><div><h2>One project core. Three pilot offers.</h2><p>Commercial finance remains the launch workspace; adjacent pilots test separate outcomes.</p></div></div><div class="tablewrap"><table><thead><tr><th>Pilot / cohort target</th><th>Offer and qualified outcome</th><th>Price experiment · CAD/team/month</th></tr></thead><tbody><tr><td>Capital origination · 3 teams</td><td>Verified sponsor, financing stage and briefing → authorized sponsor confirms a credible project and discusses financing timing or need.</td><td>$299–$799 · unvalidated</td></tr><tr><td>Contractor opportunities · 3 teams</td><td>Trade, territory, capacity and award-status shortlist → relevant decision-maker confirms a genuine pursuit opportunity.</td><td>$299–$999 · unvalidated</td></tr><tr><td>Commercial real estate relationships · 2 teams</td><td>Ownership, parcel and planning chronology → owner/developer confirms a genuine property discussion with potential for a mandate.</td><td>$299–$799 · unvalidated</td></tr></tbody></table></div><p class="subtle">The adjacent offers are pilot hypotheses; dedicated contractor and real estate CRM workflows are not yet implemented. A meeting is not a loan approval, signed mandate or won contract.</p></div><div class="layout"><section><div class="panel"><h2>90-day launch sequence</h2><div class="strategyrow"><div><h3>Days 1–30 · Interview and verify</h3><p>28 interviews: 6 brokers, 8 contractors across four specialties, 4 CRE teams, 3 developers, 2 property managers, 2 design consultants, 2 lenders and 1 appraisal practice. Assemble 100 verified projects within demonstrated Metro Vancouver / Fraser Valley coverage.</p></div></div><div class="strategyrow"><div><h3>Days 31–60 · Run 8 paid pilots</h3><p>Weekly verified shortlists and dashboard use. Record research, enrichment and support time; distinguish manual service value from software value.</p></div></div><div class="strategyrow"><div><h3>Days 61–90 · Test renewal</h3><p>Offer disclosed ongoing prices, interview inactive teams, audit attributable outcomes and gross margin. Continue with the strongest retained segment or narrow scope.</p></div></div></div><div class="panel"><h2>Evidence gates</h2><ul><li>6/8 teams: save five verified projects and create an opportunity in seven days.</li><li>6/8 teams: use the workflow in three of four pilot weeks.</li><li>5/8 teams: renew at disclosed prices without exceptional discounts.</li><li>At least half: one new attributable decision-maker-confirmed qualified meeting in 30 days.</li><li>90% accuracy: independently audit 50 critical assertions; report project and contact accuracy separately.</li><li>80% of pilot-used records: key status fields verified within seven days.</li><li>30% median preparation-time reduction against a within-team baseline; 70% steady-state gross margin target.</li></ul><p class="subtle">Proposed decision gates, not achieved results. Data accuracy, freshness, time savings and margin remain unmeasured here.</p></div></section><section><div class="panel"><h2>Market model · assumptions</h2><p><b>$125.22M</b> annual Canadian subscription TAM<br><b>$12.72M</b> planned BC SAM</p><p>Expanded quantified construction and real estate core. Based on 2025 establishments, relevance filters, 90% unique-buyer adjustment, $6,000 annual price and 60% assumed BC coverage. Coverage is not measured.</p><p>Broker pool is separate and unverified: base 750 Canadian / 100 BC teams → $4.5M / $0.6M. Do not treat it as a verified census or combine it into customer evidence.</p><p class="subtle">Excludes financing principal, commissions, lead resale and success fees. Source: supplied PMF plan, October 14, 2026; not re-researched today.</p></div><div class="panel"><h2>Year-one acquisition scenario</h2><p>250 eligible teams reached → 100 demos → 30 paid pilots → 24 retained teams.</p><h3>$144,000 exit ARR</h3><p>At $6,000/year. A mixed-segment capacity scenario; no achieved revenue or current pipeline implied. Broker-only outreach requires a verified smaller pool and a recalculated funnel.</p></div></section></div><div class="panel"><div class="panelhead"><div><h2>Pilot evidence register</h2><p>${t.meeting} of ${t.teams} recorded teams report an attributable qualified meeting. Records are manually asserted, not independently audited.</p></div><button onclick="pilotForm()">Add evidence</button></div><div class="tablewrap"><table><thead><tr><th>Segment</th><th>Paid teams</th><th>Activated</th><th>3/4 weeks</th><th>Renewed</th><th>Qualified meeting</th></tr></thead><tbody>${pilotSegments.map(s=>{const x=pilotTotals(s);return `<tr><td>${esc(s)}</td><td>${x.teams}</td><td>${x.activated}</td><td>${x.weekly}</td><td>${x.renewed}</td><td>${x.meeting}</td></tr>`}).join('')}</tbody></table></div>${pilotRecords().map(r=>`<div class="strategyrow"><div><h3>${esc(r.team)} · ${esc(r.segment)}</h3><p>${esc(r.date)} · ${esc(r.origin)} · CAD ${esc(r.price)}/month</p><p>${esc(r.notes)}</p></div><button onclick="removePilot('${esc(r.id)}')">Remove</button></div>`).join('')||'<div class="empty">No pilot evidence recorded. Add a non-sensitive team alias and evidence notes after a real paid pilot starts.</div>'}</div>`}
function pilotForm(){modal('Record a paid pilot','MANUAL EVIDENCE · USE NON-SENSITIVE ALIASES',`<form id="pilotForm" class="formgrid"><label>Team alias<input name="team" maxlength="80" required placeholder="BC broker pilot A"></label><label>Primary buying segment<select name="segment">${pilotSegments.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>Pilot start date<input name="date" type="date" required></label><label>Paid monthly equivalent · CAD<input name="price" type="number" min="0.01" step="0.01" required></label><label>Discovery attribution<select name="origin"><option>Net-new discovery</option><option>Assisted existing relationship</option><option>Not yet established</option></select></label><label class="wide">Evidence and outcome notes<textarea name="notes" required minlength="20" maxlength="3000" placeholder="Record payment evidence reference, cohort period, source verification, meeting confirmation and renewal terms as applicable. Do not paste private client information."></textarea></label>${[['activated','Five verified projects saved + opportunity created in first 7 days'],['weekly','Used the workflow in 3 of 4 pilot weeks'],['renewed','Renewed at a disclosed price without exceptional discount'],['meeting','New attributable qualified meeting in 30 days, confirmed by decision-maker']].map(([key,label])=>`<label class="task wide"><input type="checkbox" name="${key}"><span>${label}</span></label>`).join('')}<label class="task wide"><input type="checkbox" name="paid" required><span>Real paid pilot confirmed; one record per independent buying team.</span></label></form>`,`<button class="primary" onclick="savePilot()">Save evidence</button>`)}
function pilotInputError(p){if(!pilotSegments.includes(p.segment))return 'Choose a pilot segment.';if(!p.team?.trim()||(p.notes||'').trim().length<20)return 'Add a team alias and supporting evidence notes.';if(!Number.isFinite(Number(p.price))||Number(p.price)<=0)return 'Record a positive paid price.';if(!/^\d{4}-\d{2}-\d{2}$/.test(p.date||'')||isNaN(Date.parse(p.date))||new Date(p.date).toISOString().slice(0,10)!==p.date||p.date>new Date().toLocaleDateString('en-CA',{timeZone:'America/Vancouver'}))return 'Use an actual pilot start date, today or earlier.';if(p.meeting&&p.origin!=='Net-new discovery')return 'This gate requires a net-new attributable meeting; keep assisted outcomes separate.';if(pilotRecords().some(r=>r.team.toLowerCase()===p.team.trim().toLowerCase()))return 'This team alias is already recorded.';return ''}
function savePilot(){const f=$('#pilotForm');if(!f.reportValidity())return;const p=Object.fromEntries(new FormData(f)),error=pilotInputError(p);if(error){toast(error);return}if(!p.paid){toast('Confirm a real paid pilot.');return}state.pilotRecords=[...pilotRecords(),{...p,team:p.team.trim(),id:String(Date.now()),activated:!!p.activated,weekly:!!p.weekly,renewed:!!p.renewed,meeting:!!p.meeting}];log('Recorded pilot evidence for '+p.team);$('#dialog').close();render();toast('Pilot evidence saved locally.')}
function removePilot(id){state.pilotRecords=pilotRecords().filter(r=>r.id!==id);save();render();toast('Pilot record removed.')}

const briefModes=['Quick brief','Standard','Investor-grade','Battlecard'];
const briefLabels={V:'Verified · operator assessed',C:'Corroborated · operator assessed',S:'Self-reported',U:'User-supplied',A:'Analyst inference',N:'Not verified',X:'Excluded namesake'};
const briefSections=[['verdict','Executive intelligence verdict','State what is known, uncertain and commercially relevant.'],['identity','Identity & corporate resolution','Legal entity, jurisdiction, domain, identifiers and excluded namesakes. Record identity bridges; name and city alone are insufficient.'],['profile','Professional profile','Roles, dated career history and credentials. Distinguish personal, team and entity experience.'],['social','Social footprint & sentiment','Attributable professional URLs and dated observations; insufficient evidence means sentiment not rated.'],['offering','Business offering & technology','Published offering and observable intake; conversion gaps are hypotheses.'],['reputation','External references & contradictions','Evidence-backed findings, contradictions, open gaps and benign explanations. No conclusions from absent results.'],['relationships','Professional relationship map','State role, company and evidence ID for each connection.'],['affiliations','Cross-company identity bridges','Separate each legal company, role and date; confirmed / probable / possible / excluded / insufficient evidence.'],['track','Project & transaction track record','Sponsor, role, stage and evidence IDs. Keep claimed completion, control and funding separate.'],['gates','Diligence & regulatory questions','Record relevant verification questions and outstanding checks; do not infer legal or credit conclusions.'],['actions','Three priorities & next conversation','Owner, proof requested and next step. Include meeting questions and an appropriate CTA.']];
function allBriefs(){return state.clientBriefs||[]}
function currentBrief(){return allBriefs().find(b=>b.id===state.selectedBrief)}
function briefStatus(b){return b.reviewedRevision===b.revision&&b.brainVersion===(state.brain?.version||0)?'Reviewed working brief':'Draft · review required'}
function touchBrief(b){b.revision++;b.reviewedRevision=null;b.updatedAt=new Date().toISOString();save()}
function briefingPage(){const b=currentBrief();return head('Know the client. Prepare the conversation.','Your October 12 Social Intelligence & Counterparty Due Diligence skill · v1.1.',`<button class="primary" onclick="newBrief()">＋ New client briefing</button>`)+`<div class="notice">Public professional information only. This MVP organizes manually supplied research and prepares a research handoff; it does not run Exa, Parallel Search or TinyFish. Sources and verification labels are operator assertions. Avoid private borrower information in this browser-local prototype.</div><div class="briefnav">${allBriefs().map(x=>`<button class="${x.id===b?.id?'selected':''}" onclick="selectBrief('${x.id}')">${esc(x.company||x.person)}<small>${esc(briefStatus(x))}</small></button>`).join('')||'<p>No briefings yet. Create one, or start from an opportunity brief.</p>'}</div>`+(b?briefEditor(b):`<div class="panel briefpanel"><h2>From research to a useful meeting</h2><div class="steps"><span>Resolve identity</span><span>Collect sources</span><span>Classify claims</span><span>Draft battlecard</span><span>Human review</span></div><p>Choose Quick brief, Standard, Investor-grade or Battlecard. Capture the client, business context, evidence, namesake exclusions, project history, financing questions and the next conversation.</p><button onclick="newBrief()">Create first briefing →</button></div>`)}
function selectBrief(id){state.selectedBrief=id;save();nav('briefing')}
function newBrief(oppId){const o=state.opps.find(o=>o.id===oppId);modal('Start a client briefing','SOCIAL INTELLIGENCE · v1.1',`<form id="newBriefForm" class="formgrid"><label>Person / professional name<input name="person" maxlength="150" value="${esc(o?.contact?.split(' · ')[0]||'')}"></label><label>Company / legal entity<input name="company" maxlength="150" value="${esc(o?.company||'')}"></label><label>Public website<input name="website" type="url" placeholder="https://"></label><label>Geography / jurisdiction<input name="geography" maxlength="150" value="${esc(o?.city||'BC')}"></label><label>Purpose<select name="purpose"><option>Commercial financing discovery</option><option>Business financing discovery</option><option>Client acquisition</option><option>Partnership / referral</option><option>Developer / investor diligence</option></select></label><label>Output mode<select name="mode">${briefModes.map(m=>`<option>${m}</option>`).join('')}</select></label><label class="wide">Project / known relationship<textarea name="context" maxlength="2000">${esc(o?'Synthetic opportunity: '+o.name+'. '+o.note:'')}</textarea></label></form><p class="subtle">Existing opportunity fields are user-supplied or synthetic context, never verified facts.</p>`,`<button class="primary" onclick="createBrief()">Create draft</button>`)}
function createBrief(){const f=$('#newBriefForm');if(!f.reportValidity())return;const p=Object.fromEntries(new FormData(f));if(!p.person.trim()&&!p.company.trim()){toast('Enter a person or company.');return}if(p.website&&!safeMarketUrl(p.website)){toast('Use a public HTTPS website without credentials.');return}const b={...p,id:'brief-'+Date.now(),revision:1,reviewedRevision:null,brainVersion:state.brain?.version||0,brainContext:state.brain?JSON.stringify(state.brain.answers):'Client Brain not activated',claims:[],sections:{},createdAt:new Date().toISOString()};state.clientBriefs=[...allBriefs(),b];state.selectedBrief=b.id;save();$('#dialog').close();nav('briefing')}
function briefEditor(b){return `<div class="panel briefpanel"><div class="panelhead"><div><span class="eyebrow">${esc(b.mode)} · revision ${b.revision}</span><h2>${esc(b.company||b.person)}</h2><p>${esc(b.person)} · ${esc(b.geography)} · ${esc(b.purpose)}</p><span class="tag">${esc(briefStatus(b))}</span></div><div class="actions"><button onclick="researchBrief('${b.id}')">Research handoff</button><button onclick="exportBrief('${b.id}')">Download brief</button></div></div><p><b>Website:</b> ${b.website?external(safeMarketUrl(b.website),esc(b.website)):'Not supplied'}<br><b>Context · user-supplied:</b> ${esc(b.context||'None supplied')}<br><b>Client Brain:</b> v${b.brainVersion||0}${b.brainVersion!==(state.brain?.version||0)?' · changed; refresh context and review again':''}</p><button onclick="refreshBriefBrain('${b.id}')">Refresh Client Brain context</button><div class="wirebox"><b>Call preparation</b><p>Confirm authority, financing purpose, amount, timing, current debt and the next decision. A project signal is not proof of financing need. For business finance, ask about cash cycle, receivables, equipment or acquisition use before suggesting a product.</p></div></div><div class="panel briefpanel"><div class="panelhead"><div><h2>Claim & evidence register</h2><p>V / C / S / U / A / N / X classification · published, event and retrieved dates remain distinct.</p></div><button onclick="claimForm('${b.id}')">＋ Add claim</button></div>${b.claims.map((c,i)=>`<article class="briefclaim"><span class="tag">${esc(c.code)} · ${esc(briefLabels[c.code])}</span><p><b>${esc(c.evidenceId)} · ${esc(c.claim)}</b></p><p>${esc(c.caveat)}</p>${c.sources.map(s=>`<p>${external(s.url,esc(s.publisher))}<small>Published: ${esc(s.published||'unknown')} · Event: ${esc(s.event||'unknown')} · Retrieved: ${esc(s.retrieved)}</small></p>`).join('')||'<small>No external source supplied.</small>'}<button onclick="removeClaim('${b.id}',${i})">Remove claim</button></article>`).join('')||'<p>No claims collected. Conclusions remain unverified.</p>'}<p class="subtle">Company websites verify statements made, not performance. Two syndicated copies are one source. Missing search results never establish misconduct or invalid licensing.</p></div><div class="panel briefpanel"><h2>Working report & meeting battlecard</h2><p>Reference evidence IDs (E1, E2…) beside each material claim. Empty sections export as “Not researched / not verified”. Save edits before reviewing or exporting.</p><form id="briefReport" onsubmit="saveBriefReport(event,'${b.id}')">${briefSections.map(([k,t,h])=>`<label class="briefsection">${esc(t)}<small>${esc(h)}</small><textarea name="${k}" rows="3" maxlength="6000">${esc(b.sections[k]||'')}</textarea></label>`).join('')}<label>Meeting talking points & questions<textarea name="talking" rows="4" maxlength="6000">${esc(b.sections.talking||'')}</textarea></label><button class="primary" type="submit">Save report draft</button></form></div><div class="panel briefpanel"><h2>Review this exact revision</h2><p>Review is a local operator record. It does not certify due diligence, authorize outreach or approve financing. Changes to claims, report or Client Brain invalidate it.</p><button onclick="reviewBrief('${b.id}')">Review sources, identity & next action →</button></div>`}
function saveBriefReport(e,id){e.preventDefault();const b=allBriefs().find(x=>x.id===id),p=Object.fromEntries(new FormData(e.target));if(JSON.stringify(b.sections)!==JSON.stringify(p)){b.sections=p;touchBrief(b)}render();toast('Report saved. Review the saved revision.')}
function refreshBriefBrain(id){const b=allBriefs().find(x=>x.id===id);b.brainVersion=state.brain?.version||0;b.brainContext=state.brain?JSON.stringify(state.brain.answers):'Client Brain not activated';touchBrief(b);render()}
function claimForm(id){modal('Add a claim with evidence','SOURCE LABELS · OPERATOR ASSESSED',`<form id="briefClaimForm" class="formgrid"><label class="wide">Exact claim<textarea name="claim" required maxlength="2000"></textarea></label><label>Evidence classification<select name="code">${Object.entries(briefLabels).map(([k,v])=>`<option value="${k}" ${k==='N'?'selected':''}>${k} — ${v}</option>`).join('')}</select></label><label class="wide">Caveat / basis / namesake exclusion<textarea name="caveat" required maxlength="2000"></textarea></label>${[1,2].map(n=>`<fieldset class="wide"><legend>Source ${n}${n===2?' · corroboration when available':''}</legend><div class="formgrid"><label>Publisher<input name="publisher${n}" maxlength="150"></label><label>Exact public HTTPS URL<input name="url${n}" type="url"></label><label>Published date<input name="published${n}" type="date"></label><label>Event date<input name="event${n}" type="date"></label><label>Retrieved date<input name="retrieved${n}" type="date"></label></div></fieldset>`).join('')}<label class="task wide"><input type="checkbox" name="primary"><span>For V/C: an authoritative source supports this exact claim; identity match checked.</span></label><label class="task wide"><input type="checkbox" name="independent"><span>For C: sources are independent, not syndicated copies.</span></label></form>`,`<button class="primary" onclick="saveBriefClaim('${id}')">Save claim</button>`)}
function briefClaimError(c){if(!briefLabels[c.code]||!c.claim.trim()||!c.caveat.trim())return 'Record the claim, classification and caveat.';for(const s of c.sources){if(!safeMarketUrl(s.url)||!s.publisher.trim()||!s.retrieved)return 'Each source needs a publisher, public HTTPS URL and retrieved date.';for(const key of ['published','event','retrieved'])if(s[key]&&(!/^\d{4}-\d{2}-\d{2}$/.test(s[key])||isNaN(Date.parse(s[key]))||new Date(s[key]).toISOString().slice(0,10)!==s[key]))return 'Use valid source dates.';if(s.retrieved>new Date().toLocaleDateString('en-CA',{timeZone:'America/Vancouver'}))return 'Retrieved date cannot be in the future.'}if(['V','C'].includes(c.code)&&(!c.primary||!c.sources.length))return 'V/C needs a supporting authoritative source and identity check.';if(c.code==='C'&&(c.sources.length<2||!c.independent||new URL(c.sources[0].url).hostname===new URL(c.sources[1].url).hostname))return 'C needs two independent sources from distinct publishers.';if(c.code==='S'&&!c.sources.length)return 'Self-reported claims need the public statement source.';return ''}
function saveBriefClaim(id){const f=$('#briefClaimForm');if(!f.reportValidity())return;const p=Object.fromEntries(new FormData(f));const c={claim:p.claim,code:p.code,caveat:p.caveat,primary:!!p.primary,independent:!!p.independent,sources:[1,2].filter(n=>p['url'+n]||p['publisher'+n]||p['retrieved'+n]||p['published'+n]||p['event'+n]).map(n=>({url:p['url'+n],publisher:p['publisher'+n],published:p['published'+n],event:p['event'+n],retrieved:p['retrieved'+n]}))};const err=briefClaimError(c);if(err){toast(err);return}const b=allBriefs().find(x=>x.id===id);c.evidenceId='E'+((b.nextEvidence||0)+1);b.nextEvidence=(b.nextEvidence||0)+1;b.claims.push(c);touchBrief(b);$('#dialog').close();render()}
function removeClaim(id,i){const b=allBriefs().find(x=>x.id===id);b.claims.splice(i,1);touchBrief(b);render()}
function briefReviewError(b){if(b.brainVersion!==(state.brain?.version||0))return 'Refresh Client Brain context first.';if(!b.sections.identity?.trim()||!b.sections.verdict?.trim()||!b.sections.actions?.trim())return 'Save identity resolution, verdict and next actions before review.';if(!b.claims.length)return 'Record evidence or an explicit N (not verified) claim first.';if(b.claims.some(c=>briefClaimError(c)))return 'Correct evidence gaps in source records before review.';return ''}
function reviewBrief(id){const b=allBriefs().find(x=>x.id===id),error=briefReviewError(b);if(error){toast(error);return}modal('Review client briefing','REVISION '+b.revision,`<p>Unverified claims may remain, with explicit gaps. Check the saved text against its sources.</p>${[['identity','Exact target and namesakes checked; affiliations are not assumed'],['claims','Each material statement cites evidence IDs; self-claims and inferences are labelled'],['privacy','Professional scope, uncertainty and privacy reviewed'],['action','Next action and outstanding financing / diligence questions are explicit']].map(([k,l])=>`<label class="task"><input type="checkbox" id="briefCheck-${k}"><span>${l}</span></label>`).join('')}`,`<button class="primary" onclick="approveBrief('${id}',${b.revision})">Record review</button>`)}
function approveBrief(id,revision){const b=allBriefs().find(x=>x.id===id);if(b.revision!==revision||briefReviewError(b)){toast('The briefing changed; review it again.');return}if(!['identity','claims','privacy','action'].every(k=>$('#briefCheck-'+k).checked)){toast('Complete all review checks.');return}b.reviewedRevision=revision;b.reviewedAt=new Date().toISOString();save();$('#dialog').close();render();toast('Review recorded for this revision.')}
function briefText(b){let keys=b.mode==='Quick brief'?['verdict','identity','actions']:b.mode==='Battlecard'?['verdict','identity','offering','actions']:briefSections.map(x=>x[0]);return '# Client briefing — '+(b.company||b.person)+'\n\n'+briefStatus(b)+' | '+b.mode+' | Revision '+b.revision+'\nSkill: social-intelligence-due-diligence v1.1 (October 12, 2026)\nPrepared: '+(b.updatedAt||b.createdAt)+'\nPerson: '+b.person+'\nCompany: '+b.company+'\nWebsite: '+(b.website||'Not supplied')+'\nGeography: '+b.geography+'\nPurpose: '+b.purpose+'\nContext (user-supplied): '+(b.context||'None')+'\nClient Brain snapshot v'+b.brainVersion+': '+b.brainContext+'\n\nManual research workspace. No automated research tools were run. Public professional scope; not a legal opinion, certified title search, background check or credit decision.\n\n'+keys.map(k=>'## '+briefSections.find(s=>s[0]===k)[1]+'\n'+(b.sections[k]||'Not researched / not verified')).join('\n\n')+'\n\n## Meeting talking points\n'+(b.sections.talking||'Confirm authority, purpose, timing, amount, current lender and next decision.')+(b.mode==='Investor-grade'?'\n\nInvestor-grade checks: sponsor track record, site control, approvals, financing proof, LP/GP and issuer roles, offering/distribution checks and disclosure annex are required where relevant. Any missing evidence remains outstanding.':'')+'\n\n## Evidence register\n'+(b.claims.map((c,i)=>c.evidenceId+' ['+c.code+' — '+briefLabels[c.code]+'] '+c.claim+'\nCaveat: '+c.caveat+'\n'+c.sources.map(s=>s.publisher+' '+s.url+' | published '+(s.published||'unknown')+' | event '+(s.event||'unknown')+' | retrieved '+s.retrieved).join('\n')).join('\n\n')||'No evidence supplied.')+'\n\nReview does not authorize external distribution, solicitation or financing. Unknown is not disproven.'}
function exportBrief(id){const b=allBriefs().find(x=>x.id===id);downloadText('client-briefing-'+id+'.md',briefText(b))}
function researchBrief(id){const b=allBriefs().find(x=>x.id===id);const text='Use social-intelligence-due-diligence v1.1. Prepare a '+b.mode+' for '+b.person+' / '+b.company+'; website '+b.website+'; geography '+b.geography+'; purpose '+b.purpose+'. User-supplied context: '+b.context+'\nClient Brain snapshot: '+b.brainContext+'\nResolve exact person/entity and exclude namesakes. Use Exa discovery, Parallel corroboration and TinyFish public first-party inspection if available; report actual tools and access limits. Seek official registries and direct primary records for material claims. Do not submit forms or contact anyone.\nBuild V/C/S/U/A/N/X claim ledger with exact URLs and published/event/retrieved dates. Check cross-company identity bridges; shared names/cities alone do not prove identity. Separate personal/team/entity track record, planned/funded financing and site control.\nCover: '+briefSections.map(s=>s[1]).join('; ')+'. Add source-backed talking points, financing questions, 3 priorities and next action. Flag public professional scope and gaps; do not invent credibility scores or conclusions from missing results. Return a draft for human review.';modal('Research handoff','NO RESEARCH DISPATCHED',`<p>Use this prompt with your research tools and the original skill. Only public professional sources should be included.</p><textarea id="briefResearchText" rows="14" style="width:100%" readonly>${esc(text)}</textarea>`,`<button onclick="downloadText('client-briefing-research.txt',document.querySelector('#briefResearchText').value)">Download research prompt</button>`)}
function briefingStandup(){return '<h3>Client briefings</h3><p>'+allBriefs().length+' local drafts · '+allBriefs().filter(b=>briefStatus(b)==='Reviewed working brief').length+' reviewed working briefs. Research and outreach are not dispatched.</p>'}

page=location.hash.slice(1)||'overview';render();
